/**
 * scenarioService.js — Scenario generation for the Social Scenario Simulator.
 *
 * One defined situation, one role, one response. Scenarios are generated by
 * Gemini through the shared AI facade when available and always fall back to a
 * deterministic, rotating library so repeated sessions stay varied. The module
 * never stores raw audio; history keeps scores and titles only.
 */

