/** Normalize a difficulty id; unknown values fall back to "easy". */
export function normalizeDifficulty(difficulty) {
  return SCENARIO_DIFFICULTY_IDS.includes(difficulty) ? difficulty : "easy";
}

/** Normalize a category id; unknown values fall back to "daily_life". */
export function normalizeCategory(category) {
  return SCENARIO_CATEGORY_IDS.includes(category) ? category : "daily_life";
}

function slugify(value) {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
}

/**
 * Build the config the UI + generators share.
 * @param {{ category?: string, difficulty?: string, signals?: object,
 *           variantSeed?: number }} input
 */
export function buildScenarioConfig({
  category = "daily_life",
  difficulty = "easy",
  signals = {},
  variantSeed = 0,
} = {}) {
  const normalizedCategory = normalizeCategory(category);
  const normalizedDifficulty = normalizeDifficulty(difficulty);
  return {
    category: normalizedCategory,
    categoryLabel: getScenarioCategoryById(normalizedCategory)?.label ?? "Daily Life",
    difficulty: normalizedDifficulty,
    difficultyLabel: getScenarioDifficultyById(normalizedDifficulty)?.label ?? "Easy",
    hintsEnabled: Boolean(signals.provideHints),
    reducedCues: Boolean(signals.simplify || signals.reduceDistractions),
    slowPace: Boolean(signals.slowPace),
    variantSeed: Number.isFinite(variantSeed) ? Math.abs(variantSeed) : 0,
  };
}

/** Pick a deterministic fallback scenario, rotating by variantSeed so repeated
 *  sessions do not repeat the same exercise when AI is unavailable. */
export function getFallbackScenario(config = {}) {
  const category = normalizeCategory(config.category);
  let pool = FALLBACK_SCENARIOS.filter((scenario) => scenario.category === category);
  if (pool.length === 0) pool = [...FALLBACK_SCENARIOS];
  const index = (config.variantSeed ?? 0) % pool.length;
  return {
    ...pool[index],
    category,
    difficulty: normalizeDifficulty(config.difficulty),
    source: "fallback",
  };
}

/**
 * Normalize an AI scenario into the module's contract. Returns null when the
 * AI output is not usable so the caller can fall back safely.
 */
export function normalizeScenario(raw, config = {}) {
  if (!raw || typeof raw !== "object") return null;
  const cues = Array.isArray(raw.cues)
    ? raw.cues.map((cue) => String(cue ?? "").trim()).filter(Boolean).slice(0, 4)
    : [];
  const situation = String(raw.situation ?? "").trim();
  const question = String(raw.question ?? "").trim();
  const suggestedResponse = String(raw.suggestedResponse ?? "").trim();
  if (!situation || !question || !suggestedResponse || cues.length === 0) return null;

  const category = normalizeCategory(raw.category ?? config.category);
  return {
    id: String(raw.id ?? "").trim() || `${slugify(raw.title) || "scenario"}-${config.variantSeed ?? 0}`,
    category,
    difficulty: normalizeDifficulty(raw.difficulty ?? config.difficulty),
    title: String(raw.title ?? "Social scenario").trim(),
    setting: String(raw.setting ?? "").trim(),
    situation,
    role: String(raw.role ?? "").trim(),
    question,
    cues,
    suggestedResponse,
    hint: String(raw.hint ?? "").trim() || null,
    source: "ai",
  };
}

/**
 * Generate a scenario for the simulator. Uses Gemini through the shared AI
 * facade when available; otherwise returns a deterministic fallback. Never
 * throws.
 * @returns {{ scenario: object, aiAvailable: boolean, source: "ai"|"fallback" }}
 */
export async function generateScenario(config, { apiKey } = {}) {
  try {
    const generated = await callAiGenerateScenario({ config, apiKey });
    const scenario = normalizeScenario(generated, config);
    if (scenario) {
      return { scenario, aiAvailable: true, source: "ai" };
    }
  } catch {
    // fall through to the deterministic pool
  }
  return { scenario: getFallbackScenario(config), aiAvailable: false, source: "fallback" };
}

// ─────────────────────────────────────────────
//  Attempt history (scores + titles only, never transcripts)
// ─────────────────────────────────────────────
function normalizeUserId(userId) {
  return userId ? String(userId) : null;
}

function attemptsStorageKey(userId) {
  return `${SCENARIO_ATTEMPTS_STORAGE_KEY}_${normalizeUserId(userId) ?? "guest"}`;
}

function readAttempts(userId) {
  try {
    const raw = localStorage.getItem(attemptsStorageKey(userId));
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeAttempts(userId, attempts) {
  try {
    localStorage.setItem(attemptsStorageKey(userId), JSON.stringify(attempts));
  } catch {
    // private mode / quota — history simply won't persist
  }
  return attempts;
}

/** Record a completed single-response practice round. Stores no transcripts. */
export function recordScenarioAttempt(
  userId,
  { scenario, evaluation, response, voiceUsed = false, now = Date.now() } = {},
) {
  if (!scenario) return readAttempts(userId);
  const record = {
    id: `attempt-${now}-${Math.random().toString(36).slice(2, 8)}`,
    scenarioId: scenario.id,
    title: scenario.title ?? "",
    category: scenario.category ?? null,
    difficulty: scenario.difficulty ?? null,
    score: evaluation?.score ?? null,
    strengths: Array.isArray(evaluation?.strengths) ? evaluation.strengths.slice(0, 3) : [],
    voiceUsed: Boolean(voiceUsed),
    usedAi: evaluation?.usedAi === true,
    completedAt: new Date(now).toISOString(),
  };
  const attempts = [record, ...readAttempts(userId)].slice(0, 60);
  return writeAttempts(userId, attempts);
}

export function listScenarioAttempts(userId, { limit } = {}) {
  const attempts = [...readAttempts(userId)].sort((a, b) =>
    String(b.completedAt ?? "").localeCompare(String(a.completedAt ?? "")),
  );
  return Number.isInteger(limit) && limit > 0 ? attempts.slice(0, limit) : attempts;
}

export function getScenarioAttemptStats(userId) {
  const attempts = readAttempts(userId);
  const scores = attempts.filter((attempt) => Number.isFinite(attempt.score)).map((attempt) => attempt.score);
  return {
    totalAttempts: attempts.length,
    averageScore: scores.length > 0 ? Math.round(scores.reduce((sum, score) => sum + score, 0) / scores.length) : null,
  };
}

